declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';if(!v700_module_enabled('tourism')){http_response_code(404);exit('Tourism module is disabled for this tenant.');}$attractions=v700_rows("SELECT * FROM tourism_attractions_v700 WHERE tenant_id=? AND status='active' ORDER BY featured DESC,id DESC LIMIT 12",[v700_tid()]);$hotels=v700_rows("SELECT * FROM tourism_hotels_v700 WHERE tenant_id=? AND status='active' ORDER BY featured DESC,verified DESC,id DESC LIMIT 12",[v700_tid()]);$restaurants=v700_rows("SELECT * FROM tourism_restaurants_v700 WHERE tenant_id=? AND status='active' ORDER BY featured DESC,verified DESC,id DESC LIMIT 12",[v700_tid()]);$packages=v700_rows("SELECT * FROM tourism_packages_v700 WHERE tenant_id=? AND status='active' ORDER BY featured DESC,id DESC LIMIT 12",[v700_tid()]);$st=v700_tourism_stats();v700_track('tourism','browse');v700_public_header('Tourism, Hotels & Restaurant Booking','Explore local attractions, hotels, restaurants and city tour packages.','tourism');?>
<main><section class="v700-hero"><div class="v700-shell v700-hero-grid"><div><span class="v700-kicker">✦ EXPLORE THE CITY</span><h1>Stay. Eat. Discover. Book.</h1><p>A complete tenant-aware tourism portal for local attractions, hotels, restaurant reservations and curated tour packages.</p><div class="v700-actions"><a class="v700-btn primary" href="#hotels">Find Hotel</a><a class="v700-btn secondary" href="#restaurants">Book Restaurant</a><a class="v700-btn secondary" href="/tourism-account.php">My Bookings</a></div></div><div class="v700-orbit"><div class="core">✦</div><div class="sat s1"><b><?=$st['attractions']?></b><span>Attractions</span></div><div class="sat s2"><b><?=$st['hotels']?></b><span>Hotels</span></div><div class="sat s3"><b><?=$st['restaurants']?></b><span>Restaurants</span></div><div class="sat s4"><b><?=$st['packages']?></b><span>Tour Packages</span></div></div></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-head"><div><h2>Places to explore</h2><p>Curated city attractions and useful visitor information.</p></div></div><div class="v700-feature-grid"><?php foreach($attractions as $a):?><div class="v700-media-card"><div class="photo" <?=!empty($a['image_url'])?'style="background-image:url(\''.e($a['image_url']).'\')"':''?>></div><div class="shade"></div><div class="copy"><span><?=e($a['category']?:'Local attraction')?> <?=$a['featured']?'· Featured':''?></span><h3><?=e($a['name'])?></h3><p><?=e($a['area']?:$a['address']?:'Shahkot area')?></p></div></div><?php endforeach;?><?php if(!$attractions):?><div class="v700-empty">No attractions published yet.</div><?php endif;?></div></div></section><section class="v700-section white" id="hotels"><div class="v700-shell"><div class="v700-head"><div><h2>Hotels & stays</h2><p>Tenant-approved accommodation with online booking requests.</p></div></div><div class="v700-grid"><?php foreach($hotels as $h):?><a class="v700-card" href="/hotel.php?id=<?=(int)$h['id']?>"><div class="icon">🏨</div><h3><?=e($h['name'])?></h3><p><?=e($h['area']?:'Local stay')?> · <?=e($h['star_rating']>0?($h['star_rating'].' ★'):'Unrated')?> <?=$h['verified']?'· Verified':''?></p><b>View rooms →</b></a><?php endforeach;?></div></div></section><section class="v700-section soft" id="restaurants"><div class="v700-shell"><div class="v700-head"><div><h2>Restaurants</h2><p>Reserve a table at participating local restaurants.</p></div></div><div class="v700-grid"><?php foreach($restaurants as $r):?><a class="v700-card" href="/restaurant.php?id=<?=(int)$r['id']?>"><div class="icon">🍽</div><h3><?=e($r['name'])?></h3><p><?=e($r['cuisine']?:'Restaurant')?> · <?=e($r['area']?:'Shahkot')?> <?=$r['verified']?'· Verified':''?></p><b>Book a table →</b></a><?php endforeach;?></div></div></section><section class="v700-section white"><div class="v700-shell"><div class="v700-head"><div><h2>Tour packages</h2><p>Book local experiences and curated tours.</p></div></div><div class="v700-grid"><?php foreach($packages as $p):?><div class="v700-card"><div class="icon">🧭</div><h3><?=e($p['title'])?></h3><p><?=e($p['duration_text']?:'Flexible schedule')?> · Start <?=e($p['start_location']?:'Shahkot')?></p><b><?=v700_money((float)$p['price_per_person'])?> / person</b><div class="v700-actions"><a class="v700-btn primary" href="/tourism-book.php?package=<?=(int)$p['id']?>">Book Tour</a></div></div><?php endforeach;?></div></div></section></main><?php v700_public_footer(); ?>
